$checks=0;function ok(bool $value,string $message):void{global $checks;if(!$value)throw new RuntimeException($message);$checks++;}function fails(callable $fn,string $code):void{try{$fn();throw new RuntimeException("Falha esperada: $code");}catch(ModuleAttachmentException $e){ok($e->errorCode===$code,"Código inesperado: {$e->errorCode}");}}
function keyFor(array $payload,?string $secret=null):string{$encoded=rtrim(strtr(base64_encode(json_encode($payload,JSON_UNESCAPED_SLASHES)),'+/','-_'),'=');return 'GDA1.'.$encoded.'.'.($secret??str_repeat('A',43));}
