$challenge=str_repeat('c',64);$validator=new ModuleManifestValidator($policy);$valid=$validator->validate(manifest($challenge),$challenge,'gda-caixas');ok($valid['module']['name']==='Caixas','Manifesto válido rejeitado.');$bad=manifest('outro');fails(fn()=>$validator->validate($bad,$challenge,'gda-caixas'),'incompatible_manifest');$bad=manifest($challenge);unset($bad['module']['version']);fails(fn()=>$validator->validate($bad,$challenge,'gda-caixas'),'incompatible_manifest');$bad=manifest($challenge);$bad['module']['admin_url']='https://evil.test/admin';fails(fn()=>$validator->validate($bad,$challenge,'gda-caixas'),'endpoint_denied');$bad=manifest($challenge);$bad['connection']['key_consumed']=false;fails(fn()=>$validator->validate($bad,$challenge,'gda-caixas'),'incompatible_manifest');
